document.addEventListener("DOMContentLoaded",function(){var i=document.getElementById("dbw-filter-toggle"),r=document.getElementById("dbw-filter-container");if(i&&r&&i.addEventListener("click",function(e){e.preventDefault(),r.classList.toggle("is-expanded");var t=r.classList.contains("is-expanded");i.setAttribute("aria-expanded",t?"true":"false")}),!("IntersectionObserver"in window)){document.querySelectorAll(".dbw-property-card, .dbw-main-col .dbw-section").forEach(function(e){e.classList.add("is-visible")});return}var o=document.querySelectorAll("#dbw-immo-suite .dbw-property-card");if(o.length){var s=new IntersectionObserver(function(e){var t=[];e.forEach(function(n){n.isIntersecting&&(t.push(n.target),s.unobserve(n.target))}),t.forEach(function(n,d){n.style.setProperty("--stagger",d*80+"ms"),n.classList.add("is-visible")})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});o.forEach(function(e){s.observe(e)})}var a=document.querySelectorAll("#dbw-immo-suite .dbw-main-col .dbw-section");if(a.length){var c=new IntersectionObserver(function(e){e.forEach(function(t){t.isIntersecting&&(t.target.classList.add("is-visible"),c.unobserve(t.target))})},{threshold:.1,rootMargin:"0px 0px -60px 0px"});a.forEach(function(e){c.observe(e)})}});
